@Override public void execute(Task task){
  try {
    processOutputDirectory(this.task.getDestinationDir(),this.task.getClasspath());
  }
  catch (IOException exception) {
    throw new GradleException("Error accessing file system",exception);
  }
  catch (LinkageError | SecurityException | Error | IndexOutOfBoundsException | IllegalStateException e) {
    throw new GradleException("Unexpected error during processing", e);
  }
}
